#include "RavenShipActor.h"
ARavenShipActor::ARavenShipActor(){PrimaryActorTick.bCanEverTick=false;Root=CreateDefaultSubobject<USceneComponent>(TEXT("Root"));SetRootComponent(Root);}
FName ARavenShipActor::SocketForSlot(EDeadlockShipSlot S)const{switch(S){case EDeadlockShipSlot::Core:return TEXT("SF_Core");case EDeadlockShipSlot::Cockpit:return TEXT("SF_Cockpit");case EDeadlockShipSlot::Wing:return TEXT("SF_Wing");case EDeadlockShipSlot::Engine:return TEXT("SF_Engine");case EDeadlockShipSlot::Weapon:return TEXT("SF_Weapon");case EDeadlockShipSlot::Cargo:return TEXT("SF_Cargo");default:return TEXT("SF_Utility");}}
bool ARavenShipActor::InstallPart(UDeadlockShipPartData* P){if(!P||!P->Mesh)return false;ClearSlot(P->Slot);const FName N=*FString::Printf(TEXT("ShipPart_%d"),(int32)P->Slot);UStaticMeshComponent* C=NewObject<UStaticMeshComponent>(this,N);C->RegisterComponent();C->SetStaticMesh(P->Mesh);C->AttachToComponent(Root,FAttachmentTransformRules::SnapToTargetNotIncludingScale,P->RequiredSocket.IsNone()?SocketForSlot(P->Slot):P->RequiredSocket);Components.Add(P->Slot,C);return true;}
void ARavenShipActor::ClearSlot(EDeadlockShipSlot S){if(TObjectPtr<UStaticMeshComponent>* C=Components.Find(S)){if(*C)(*C)->DestroyComponent();Components.Remove(S);}}